const napA = (ms) => new Promise((resolve) => setTimeout(resolve, ms, "A"));
const napB = (ms) => new Promise((resolve) => setTimeout(() => resolve, ms));
const napC = (ms) => new Promise((resolve) => setTimeout(resolve("C"), ms));

setTimeout(() => console.log("timer"), 20);
napA(40).then((value) => console.log(value));
napB(10).then(() => console.log("B"));
napC(40).then((value) => console.log(value));
